def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.
    Builds a mapping from encoded letters to their original letters. If a contradiction
    is found during mapping construction, or not all letters are represented in the
    mapping, the function returns "Failed".

    Args:
        encoded: A string representing the encoded information.
        original: A string representing the original information corresponding to the encoded string.
        message: A string representing the encrypted message to be decoded.

    Returns:
        The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Verify that encoded and original have the same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction
        else:
            mapping[e_char] = o_char

    # Ensure all 26 uppercase letters are mapped
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    try:
        decoded_chars = [mapping[ch] for ch in message]
    except KeyError:
        return "Failed"

    return "".join(decoded_chars)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
                                as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("Parameter 'n' must be an integer.")
    if n < 0:
        raise ValueError("Parameter 'n' must be non‑negative.")
    if not isinstance(rules, list):
        raise TypeError("Parameter 'rules' must be a list.")
    for rule in rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise TypeError("Each rule must be a tuple of two integers.")
        x, y = rule
        if not isinstance(x, int) or not isinstance(y, int):
            raise TypeError("Rule digits must be integers.")
        if x < 0 or x > 9 or y < 0 or y > 9:
            raise ValueError("Rule digits must be single decimal digits (0‑9).")

    # Build mapping from digit character to set of possible transformed digits
    mapping = {}
    for x, y in rules:
        mapping.setdefault(str(x), set()).add(str(y))
    # Convert to list for iteration
    for k in mapping:
        mapping[k] = list(mapping[k])

    start_str = str(n)
    visited = {n}
    queue = [start_str]

    while queue:
        current = queue.pop(0)
        digits = list(current)
        for idx, digit in enumerate(digits):
            if digit in mapping:
                for new_digit in mapping[digit]:
                    new_digits = digits.copy()
                    new_digits[idx] = new_digit
                    new_number = int(''.join(new_digits))
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(''.join(new_digits))
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    This function takes a potential criminal's name (scenario) and a set of liars (liar_count) and checks if
    the statements made by all participants are consistent with this scenario, disregarding any statements
    about the day of the week.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    if not isinstance(scenario, str) or not isinstance(liar_count, set) or not isinstance(statements, dict) or not isinstance(days_of_week, set):
        return False

    # Normalize names to a consistent case to avoid mismatches (assuming names are case-insensitive)
    scenario_normalized = scenario.strip().upper()
    liar_count_normalized = {name.strip().upper() for name in liar_count}
    # Prepare a set of day words for quick lookup; assume days_of_week are uppercase or mixed case
    days_normalized = {day.strip().upper() for day in days_of_week}

    def is_statement_about_day(stmt: str) -> bool:
        """Return True if statement mentions any day of the week."""
        # Simple token-based check; split on whitespace and punctuation
        words = [w.strip('.,!?').upper() for w in stmt.replace(',', ' ').replace(';', ' ').split()]
        return any(word in days_normalized for word in words)

    def evaluate_statement(stmt: str) -> bool | None:
        """
        Evaluate a statement about guilt. Return True if the statement is true under the scenario,
        False if false, or None if the statement cannot be interpreted as a guilt statement.
        """
        stmt_clean = stmt.lower().strip()
        # Handle "I am guilty." / "I am not guilty."
        if stmt_clean.startswith("i am guilty"):
            return scenario_normalized == "I"  # This would only make sense if statement from same person; unrealistic for this scenario
        if stmt_clean.startswith("i am not guilty"):
            return scenario_normalized != "I"

        # Handle patterns like "NAME is guilty." / "NAME is not guilty."
        if " is guilty" in stmt_clean:
            parts = stmt_clean.split(" is guilty")
            if len(parts) != 2:
                return None
            subject = parts[0].strip().upper()
            return scenario_normalized == subject
        if " is not guilty" in stmt_clean:
            parts = stmt_clean.split(" is not guilty")
            if len(parts) != 2:
                return None
            subject = parts[0].strip().upper()
            return scenario_normalized != subject
        # If statement is just the subject name with guilty/innocent adjectives, ignore
        return None

    # Go through each participant and evaluate their statements
    for participant, stmts in statements.items():
        if not isinstance(stmts, list):
            continue  # Skip invalid entry
        participant_norm = participant.strip().upper()
        expected_truth = participant_norm not in liar_count_normalized
        for stmt in stmts:
            if not isinstance(stmt, str):
                continue
            if is_statement_about_day(stmt):
                continue
            result = evaluate_statement(stmt)
            if result is None:
                # Non‑guilt related statement, ignore
                continue
            if expected_truth:
                if not result:
                    return False
            else:
                if result:
                    return False
    return True

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Compute the maximum total value of herbs that can be picked within the given time limit T.
    Each herb can be chosen at most once. Returns 0 for invalid or edge cases.
    """
    # Basic validation
    if not isinstance(T, int) or T < 0:
        return 0
    if not isinstance(herbs, list):
        return 0

    # Filter out invalid herb entries
    valid_herbs = []
    for herb in herbs:
        if (
            isinstance(herb, tuple)
            and len(herb) == 2
            and isinstance(herb[0], int)
            and isinstance(herb[1], int)
            and herb[0] > 0
            and herb[1] >= 0
        ):
            # Do not exceed the time capacity with a single herb
            if herb[0] <= T:
                valid_herbs.append(herb)

    if not valid_herbs:
        return 0

    # 1D DP for 0/1 knapsack
    dp = [0] * (T + 1)
    for time_cost, value in valid_herbs:
        for cap in range(T, time_cost - 1, -1):
            new_val = dp[cap - time_cost] + value
            if new_val > dp[cap]:
                dp[cap] = new_val

    return dp[T] if dp else 0

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position `i`, the heights of students
    increase from the start to `i` and decrease from `i` to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if heights is None:
        raise TypeError("heights must be a list of integers")
    if not isinstance(heights, list):
        raise TypeError("heights must be a list of integers")
    if any(not isinstance(h, int) for h in heights):
        raise TypeError("heights must contain only integers")

    n = len(heights)
    if n <= 1:
        return 0  # No removal needed for 0 or 1 student

    # Longest increasing subsequence (LIS) ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence (LDS) starting at each index
    dec = [1] * n
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Compute maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1  # peak counted twice
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals = total students - maximum bitonic subsequence length
    return n - max_bitonic
